async function serviceCommand(command,data,next){try{const r=await api('service/'+command,data);banner.textContent='Immediate action completed. Revision '+r.revision+'.';servicesSnapshot=await api('services');if(next)await next();}catch(e){serviceError(e);}}
function newService(){serviceEditor={id:'',base:servicesSnapshot.revision,generation:0,step:0,isNew:true,service:{type:'http',name:'',description:'',no_auth:true,tls:{verify:true},destinations:[{id:'primary',base_url:''}],credentials:[],access:{users:[]},policy:{mode:'deny',rules:[]}},credentials:[]};editorDirty=false;renderEditor(0);}
