function destinationHelp(input,text){const help=el('p',text);help.id=input.id+'-help';help.className='field-help';input.after(help);input.setAttribute('aria-describedby',help.id);return help;}
function destinationHostHelp(kind){return kind==='suffix'?'A suffix allows this DNS name and its subdomains. For example, example.org also allows api.example.org. It does not allow notexample.org.':kind==='regex'?'A regular expression matches hostnames. For example, ^api[0-9]+\\.example\\.org$ allows api1.example.org. Keep anchors to limit the whole hostname.':'Exact allows only the named hostname. With no override, requests use the hostname in the server URL.';}
